def transform(grid):
    g = np.array(grid).copy()
    bg = background(g)
    pts = [(y, x) for y in range(g.shape[0]) for x in range(g.shape[1]) if g[y, x] != bg]
    from collections import defaultdict
    rows, cols = defaultdict(list), defaultdict(list)
    for y, x in pts:
        rows[y].append(x)
        cols[x].append(y)
    for y in sorted(rows):
        xs = sorted(rows[y])
        for a, b in zip(xs, xs[1:]):
            c = g[y, a]
            for x in range(a + 1, b):
                if g[y, x] == bg:
                    g[y, x] = c
            emit(g, f"Row {y}: connect cells at x={a} and x={b} with a horizontal line.")
    for x in sorted(cols):
        ys = sorted(cols[x])
        for a, b in zip(ys, ys[1:]):
            c = grid[a][x]
            for y in range(a + 1, b):
                if g[y, x] == bg:
                    g[y, x] = c
            emit(g, f"Column {x}: connect cells at y={a} and y={b} with a vertical line.")
    emit(g, "All aligned pairs connected; isolated cells stay alone.")
    return g
